REVOKE SELECT ON TABLE public.comments FROM PUBLIC, anon, authenticated;
REVOKE SELECT (id, post_id, display_name, body, status, created_at, status_id, parent_id, author_telegram_id) ON TABLE public.comments FROM PUBLIC, anon, authenticated;
GRANT SELECT (id, post_id, parent_id, display_name, body, status, status_id, created_at) ON TABLE public.comments TO anon, authenticated;
REVOKE ALL PRIVILEGES ON TABLE public.web_sessions FROM PUBLIC, anon, authenticated;
REVOKE SELECT (token, telegram_id, created_at, expires_at, user_agent), INSERT (token, telegram_id, created_at, expires_at, user_agent), UPDATE (token, telegram_id, created_at, expires_at, user_agent), REFERENCES (token, telegram_id, created_at, expires_at, user_agent) ON TABLE public.web_sessions FROM PUBLIC, anon, authenticated;
DO $$ DECLARE r text; c text; BEGIN FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF has_column_privilege(r,'public.comments','author_telegram_id','SELECT') THEN RAISE EXCEPTION 'Telegram identity still readable by %', r; END IF; IF NOT has_column_privilege(r,'public.comments','body','SELECT') OR NOT has_column_privilege(r,'public.comments','post_id','INSERT') THEN RAISE EXCEPTION 'Public comment access unexpectedly lost for %', r; END IF; FOREACH c IN ARRAY ARRAY['token','telegram_id','created_at','expires_at','user_agent'] LOOP IF has_column_privilege(r,'public.web_sessions',c,'SELECT') OR has_column_privilege(r,'public.web_sessions',c,'INSERT') OR has_column_privilege(r,'public.web_sessions',c,'UPDATE') THEN RAISE EXCEPTION 'Session access remains for % on %', r, c; END IF; END LOOP; END LOOP; IF NOT has_table_privilege('service_role','public.web_sessions','SELECT') OR NOT has_table_privilege('service_role','public.comments','SELECT') THEN RAISE EXCEPTION 'Server access unexpectedly lost'; END IF; END $$;
NOTIFY pgrst, 'reload schema';